// ===== 17mb 聚合源公共配置（rrssk 范式：HOST_TEMPLATE_MAP + TEMPLATES + 规则分发）=====
var HOST_TEMPLATE_MAP = {
  'https://www.manyanshu.com': 'legacy',
  'https://www.zilanwenxue.com': 'legacy',
  'https://www.xiansange.com': 'legacy',
  'https://www.chunzhushu.com': 'boot',
  'http://www.yueyingxs.com': 'boot',
  'http://www.yujiuxs.com': 'boot',
  'http://www.qingniange.com': 'boot',
  'https://m.yunmustories.com': 'mobile',
  'https://m.caijingbooks.com': 'mobile'
};
var HOSTS = [];
for (var M17_HK in HOST_TEMPLATE_MAP) { if (HOST_TEMPLATE_MAP.hasOwnProperty(M17_HK)) HOSTS.push(M17_HK); }

// 模板名 -> 处理函数（规则只调用 M17_EXPLORE/M17_TOC/M17_CONTENT/M17_NEXT 四个入口）
var TEMPLATES = {
  legacy: {list: 'M17_LIST_LEGACY', toc: 'M17_TOC_LEGACY', content: 'M17_CONTENT_LEGACY', next: 'M17_NEXT_LEGACY'},
  boot:   {list: 'M17_LIST_BOOT',   toc: 'M17_TOC_BOOT',   content: 'M17_CONTENT_BOOT',   next: 'M17_NEXT_ANY'},
  mobile: {list: 'M17_LIST_MOBILE', toc: 'M17_TOC_MOBILE', content: 'M17_CONTENT_MOBILE', next: 'M17_NEXT_ANY'}
};

function M17_NORM(u) {
  var s = String(u || '').toLowerCase();
  var m = s.match(/^(?:https?:\/\/)?([^\/]+)/);
  var h = m ? m[1] : s;
  if (h.indexOf('www.') === 0) h = h.substring(4);
  return h.replace(/\/+$/, '');
}
function M17_HOST(u, jv, sv) {
  var m = String(u || '').match(/^(https?:\/\/[^/]+)/i);
  if (m) return m[1];
  var s = '';
  try { s = String(sv && sv.get ? sv.get('my17_site') : ''); } catch (e) {}
  if (!s) { try { s = String(jv && jv.get ? jv.get('my17_site') : ''); } catch (e2) {} }
  if (s) return s;
  return HOSTS[0];
}
function M17_TMPL(u, jv, sv) {
  var n = M17_NORM(M17_HOST(u, jv, sv));
  for (var k in HOST_TEMPLATE_MAP) {
    if (HOST_TEMPLATE_MAP.hasOwnProperty(k) && M17_NORM(k) === n) return HOST_TEMPLATE_MAP[k];
  }
  return 'legacy';
}
function M17_LIST() { return new Packages.java.util.ArrayList(); }
function M17_ABS(u, base) {
  var s = String(u || '').trim();
  if (!s) return '';
  if (/^https?:/i.test(s)) return s;
  if (s.charAt(0) === '/') return String(base || '').replace(/\/+$/, '') + s;
  return String(base || '').replace(/\/+$/, '') + '/' + s;
}
function M17_CLEAN(s) {
  return String(s || '')
    .replace(/<[^>]*>/g, '')
    .replace(/&#xe8[0-9a-fA-F]{2};?/g, '')
    .replace(/&#x([0-9a-fA-F]+);/g, function (a, b) {
      var n = parseInt(b, 16);
      return (n < 32 || n > 126) ? '' : String.fromCharCode(n);
    })
    .replace(/&#(\d+);?/g, function (a, b) {
      var n = parseInt(b, 10);
      return (n < 32 || n > 126) ? '' : String.fromCharCode(n);
    })
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
function M17_SET_SITE(v){
  var u=String(v||'');
  try{this.source.put('my17_site',u)}catch(e){}
  try{this.java.put('my17_site',u)}catch(e2){}
  try{this.java.refreshExplore()}catch(e3){}
}
function M17_JSON(list, o) {
  try { list.add(JSON.stringify(o)); } catch (e) {}
}
// ===== 发现/搜索列表解析：三套模板统一返回 java.util.ArrayList(JSON字符串) =====
function M17_LIST_LEGACY(jv, html, base) {
  var h = String(html || ''), out = M17_LIST(), seen = {}, BASE = M17_HOST(base, jv);
  function add(u, n, a, l, cv) {
    if (!u || !n) return;
    u = M17_ABS(u, BASE);
    if (!u || seen[u]) return;
    seen[u] = 1;
    M17_JSON(out, {name: n, url: u, author: a || '', lastChapter: l || '', coverUrl: cv || ''});
  }
  var parts = h.split(/<div class="item"/);
  for (var i = 1; i < parts.length; i++) {
    var p = parts[i];
    var m = p.match(/<dt><a href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/);
    if (!m) continue;
    var a = p.match(/<div class="btm">(?:<a[^>]*>([^<]*)<\/a>|([^<]*))/);
    var cv = p.match(/data-original="([^"]+)"/) || p.match(/src="([^"]+)"/);
    add(m[1], M17_CLEAN(m[2]), a ? M17_CLEAN(a[1] || a[2]) : '', '', cv ? cv[1] : '');
  }
  var lis = h.match(/<li>[\s\S]*?<\/li>/g) || [];
  for (var j = 0; j < lis.length; j++) {
    var li = lis[j];
    var m2 = li.match(/class="s2"><a href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/);
    if (!m2) continue;
    var au = li.match(/class="s4">([^<]*)/) || li.match(/class="s5">([^<]*)/);
    var lc = li.match(/class="s3"><a[^>]*>([\s\S]*?)<\/a>/);
    add(m2[1], M17_CLEAN(m2[2]), au ? M17_CLEAN(au[1]) : '', lc ? M17_CLEAN(lc[1]) : '');
  }
  var cards = h.split(/<div class="item"/);
  for (var q = 1; q < cards.length; q++) {
    var cd = cards[q];
    var m3 = cd.match(/<dt><a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/);
    if (!m3) continue;
    var a3 = cd.match(/<a[^>]+href="[^"]*\/author\/[^"]*"[^>]*>([\s\S]*?)<\/a>/);
    var cv3 = cd.match(/<img[^>]+src="([^"]+)"/) || cd.match(/data-original="([^"]+)"/);
    var lc3 = cd.match(/<a[^>]+target="_blank"[^>]*>([\s\S]*?)<\/a>/);
    var in3 = cd.match(/<dd[^>]*>([\s\S]*?)<\/dd>/);
    add(m3[1], M17_CLEAN(m3[2]), a3 ? M17_CLEAN(a3[1]) : '', lc3 ? M17_CLEAN(lc3[1]) : '', cv3 ? cv3[1] : '');
  }
  return out;
}
function M17_LIST_BOOT(jv, html, base) {
  var h = String(html || ''), out = M17_LIST(), seen = {}, BASE = M17_HOST(base, jv);
  var re = /<a[^>]+href="([^"]+)"[^>]+title="([^"]+)"[^>]*>/g, m;
  while ((m = re.exec(h)) !== null) {
    var u = m[1], n = M17_CLEAN(m[2]);
    if (!n || !/\/[A-Za-z0-9]{3,12}\/?$/.test(u)) continue;
    u = M17_ABS(u, BASE);
    if (seen[u]) continue;
    seen[u] = 1;
    var around = h.substring(Math.max(0, m.index - 700), Math.min(h.length, m.index + 700));
    var au = around.match(/<small[^>]*>([\s\S]*?)<\/small>/);
    var cv = around.match(/background-image\s*:\s*url\(([^)]+)\)/) || around.match(/<img[^>]+src="([^"]+)"/);
    M17_JSON(out, {name: n, url: u, author: au ? M17_CLEAN(au[1]).replace(/\s*\/\s*著$/, '') : '', lastChapter: '', coverUrl: cv ? cv[1].replace(/['"]/g, '') : ''});
  }
  return out;
}
function M17_LIST_MOBILE(jv, html, base) {
  var h = String(html || ''), out = M17_LIST(), seen = {}, BASE = M17_HOST(base, jv);
  var re = /<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g, m;
  while ((m = re.exec(h)) !== null) {
    var u = m[1];
    if (!/\/wenzhang\/\d+\/|\/info_\d+\//.test(u)) continue;
    var n = M17_CLEAN(m[2]);
    if (!n || n.length > 80) continue;
    u = M17_ABS(u, BASE);
    if (seen[u]) continue;
    seen[u] = 1;
    var around = h.substring(Math.max(0, m.index - 500), Math.min(h.length, m.index + 900));
    var au = around.match(/class="con_d2"[\s\S]*?<a[^>]*>([^<]*)<\/a>/) || around.match(/作者[：:]\s*<a[^>]*>([^<]*)<\/a>/);
    var cv = around.match(/<img[^>]+src="([^"]+)"/);
    M17_JSON(out, {name: n, url: u, author: au ? M17_CLEAN(au[1]) : '', lastChapter: '', coverUrl: cv ? cv[1] : ''});
  }
  return out;
}
function M17_EXPLORE(jv, html, base) {
  var t = M17_TMPL(base, jv);
  if (t === 'boot') return M17_LIST_BOOT(jv, html, base);
  if (t === 'mobile') return M17_LIST_MOBILE(jv, html, base);
  return M17_LIST_LEGACY(jv, html, base);
}
// ===== 目录解析：详情/发现页均为单页全量目录 =====
function M17_TOC_LEGACY(jv, html, base) {
  var h = String(html || ''), out = M17_LIST(), seen = {}, BASE = M17_HOST(base, jv);
  var re = /<a href="([^"]+)" title="([^"]*)" rel="chapter"><dd>([\s\S]*?)<\/dd><\/a>/g, m;
  while ((m = re.exec(h)) !== null) {
    var u = M17_ABS(m[1], BASE), n = M17_CLEAN(m[2]) || M17_CLEAN(m[3]);
    if (!n || seen[u]) continue;
    seen[u] = 1;
    M17_JSON(out, {name: n, url: u});
  }
  return out;
}
function M17_TOC_BOOT(jv, html, base) {
  var h = String(html || ''), out = M17_LIST(), seen = {}, BASE = M17_HOST(base, jv);
  var p = h.match(/<div class="panel-chapterlist"[\s\S]*?<\/div>/);
  var seg = p ? p[0] : h;
  var re = /<dd[^>]*>\s*<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>\s*<\/dd>/g, m;
  while ((m = re.exec(seg)) !== null) {
    var u = m[1], n = M17_CLEAN(m[2]);
    if (!n || /点击查看|全部章节/.test(n) || /1-1\.html/.test(u)) continue;
    u = M17_ABS(u, BASE);
    if (seen[u]) continue;
    seen[u] = 1;
    M17_JSON(out, {name: n, url: u});
  }
  return out;
}
function M17_TOC_MOBILE(jv, html, base) {
  var h = String(html || ''), out = M17_LIST(), seen = {}, BASE = M17_HOST(base, jv);
  var segAll = h.match(/<div class="info_list">[\s\S]*?<\/ul>/);
  var seg = segAll ? segAll[0] : h;
  var re = /<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g, m;
  while ((m = re.exec(seg)) !== null) {
    var u = m[1], n = M17_CLEAN(m[2]);
    if (!/\/wenzhang\/\d+\/[A-Za-z0-9_]+\.(?:asp|html)|\/info_\d+\/[A-Za-z0-9_]+\.(?:aspx|html)/.test(u)) continue;
    u = M17_ABS(u, BASE);
    if (!n || seen[u]) continue;
    seen[u] = 1;
    M17_JSON(out, {name: n, url: u});
  }
  return out;
}
function M17_TOC(jv, html, base, book) {
  var u = base || (book && (book.url || book.tocUrl)) || '';
  function parse(h) {
    var t = M17_TMPL(u, jv);
    if (t === 'boot') return M17_TOC_BOOT(jv, h, u);
    if (t === 'mobile') return M17_TOC_MOBILE(jv, h, u);
    return M17_TOC_LEGACY(jv, h, u);
  }
  var r = parse(html);
  // 详情页偶发 500/空壳时目录为 0，只重取详情页本身，不重搜
  for (var i = 0; i < 2 && r.size() === 0 && u; i++) {
    try {
      var h2 = String(jv.ajax(u));
      if (h2.length > 5000) r = parse(h2);
    } catch (e) {}
    if (r.size() > 0) break;
    try { Packages.java.lang.Thread.sleep(500); } catch (e2) {}
  }
  return r;
}

// ===== 正文：17mb 家族 contentreplace.js 混淆字还原 + 通用广告清洗 =====
var M17_FROM = ['瑟','幸','银','因','经','乃','机','吧','纯','弟','柔','榜','血','草','汝','屯','剑','差','养','师','思','椿','曹','鳃','伴','应','跟','晴','当','阿','屋','创','博','旧','摄','经','跨','初','鼎','么','西','皮','演','叶','归','腆','梢','凤','录','市','丑','杨','差','罗','鈤'];
var M17_TO = ['色','性','淫','阴','茎','奶','鸡','巴','唇','蒂','肉','棒','穴','操','乳','臀','贱','擦','痒','湿','私','春','潮','塞','瓣','硬','根','情','裆','啊','唔','床','勃','究','射','精','胯','粗','顶','摸','翕','屁','眼','液','龟','舔','搔','缝','撸','舐','抽','阳','插','裸','日'];
function M17_DECODE(h, c) {
  var am = String(h || '').match(/arrrp\s*=\s*\[([\s\S]*?)\]/);
  if (!am) return c;
  var arr = am[1].split(','), set = {}, ix = 0, dec = '', i;
  for (i = 0; i < M17_FROM.length; i++) { set[M17_FROM[i]] = 1; set[M17_TO[i]] = 1; }
  for (i = 0; i < arr.length; i++) arr[i] = String(arr[i]).replace(/^['"]|['"]$/g, '').trim();
  for (i = 0; i < c.length; i++) {
    var ch = c.charAt(i);
    if (set[ch]) {
      var rp = arr[ix++];
      dec += ((rp !== undefined && rp !== '') ? M17_TO[parseInt(rp, 10)] : ch);
    } else dec += ch;
  }
  return dec;
}
function M17_CLEAN_CONTENT(h, c) {
  c = M17_DECODE(h, c);
  c = c.replace(/【[^<>]*<a\s+href="[^"]*"[^>]*>[\s\S]*?<\/a>[^<>]*】/g, '');
  c = c.replace(/请记住本书首发域名[^<]*/g, '').replace(/手机版阅读网址[：:]?wap\.?/g, '').replace(/内容未完，下一页继续阅读/g, '');
  c = c.replace(/M\.\./g, '').replace(/www\.[A-Za-z0-9.-]+\.[a-z]{2,8}/g, '');
  return c;
}
function M17_CONTENT(jv, html, base, book) {
  var h = String(html || ''), u = base || (book && (book.url || book.tocUrl)) || '';
  var t = M17_TMPL(u, jv);
  var re = t === 'mobile'
    ? /<div id="chapter_con"[^>]*>([\s\S]*?)<\/div>/
    : /<div id="chapter">([\s\S]*?)<\/div>/;
  var m = h.match(re);
  if (!m) return null;
  return M17_CLEAN_CONTENT(h, m[1]);
}
function M17_NEXT_ANY(jv, html, base) {
  var h = String(html || ''), BASE = M17_HOST(base, jv);
  var re = /<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g, m;
  while ((m = re.exec(h)) !== null) {
    if (String(m[2]).indexOf('下一页') < 0) continue;
    return M17_ABS(m[1], BASE);
  }
  return null;
