function decode(b){
  var bmp=Packages.android.graphics.BitmapFactory.decodeByteArray(b,0,b.length);
  if(!bmp)return null;
  var w=bmp.getWidth(),h=bmp.getHeight(),pix=[],x,y,c,gray;
  var isCJ=IS_CJ,SW=isCJ?16:12,SH=isCJ?24:12,TS=isCJ?49:19,BITS=SW*SH,TH=isCJ?200:230;
  for(y=0;y<h;y++){for(x=0;x<w;x++){
    c=bmp.getPixel(x,y);
    gray=((c>>16&255)*299+(c>>8&255)*587+(c&255)*114)/1000;
    pix[y*w+x]=(gray<TH)?1:0;
  }}
  var tpl=jv.base64DecodeToByteArray(isCJ?TBCJ:TB);
  if(!tpl||tpl.length%TS)return null;
  var slots=[[0,32],[40,74],[88,124],[136,168]],out='',minScore=999;
  for(var s=0;s<4;s++){
    var x0=slots[s][0],x1=slots[s][1],minx=999,maxx=-1,miny=999,maxy=-1;
    for(y=3;y<39;y++){for(x=x0;x<x1;x++){
      if(pix[y*w+x]){if(x<minx)minx=x;if(x>maxx)maxx=x;if(y<miny)miny=y;if(y>maxy)maxy=y;}
    }}
    if(maxx<0)return null;
    var sw=maxx-minx+1,sh=maxy-miny+1,bm=[];
    for(var yy=0;yy<SH;yy++){
      var sy=Math.min(sh-1,Math.floor((yy+0.5)*sh/SH));
      for(var xx=0;xx<SW;xx++){
        var sx=Math.min(sw-1,Math.floor((xx+0.5)*sw/SW));
        bm.push(pix[(miny+sy)*w+minx+sx]?1:0);
      }
    }
    var best=-1,bc='?';
    for(var ti=0;ti<tpl.length/TS;ti++){
      var off=ti*TS,score=0;
      for(var q=0;q<BITS;q++){
        var by=tpl[off+1+(q>>3)]&255,bit=(by>>(7-(q&7)))&1;
        if(bit===bm[q])score++;
      }
      if(score>best){best=score;bc=CH.charAt(tpl[off]&255).toLowerCase()}
    }
    if(best<minScore)minScore=best;
    out+=bc;
  }
  return {code:out,score:minScore};
}
function ocr(){
